<template>
    <teleport to="body">
        <transition name="imageAni">
            <div class="image-cropper" v-show="showCropper">
                <headbar text="剪裁图像"></headbar>
                <div class="cropper-wrapper">
                    <!--
                    https://github.com/xyxiao001/vue-cropper
                     centerBox 截图框是否被限制在图片里面
                     -->
                    <vue-cropper
                            ref="cropperRef"
                            :img="imgSrc"
                            :outputType="'jpeg'"
                            :canScale="true"
                            :info="false"
                            :autoCrop="true"
                            :autoCropWidth="cropWidth"
                            :autoCropHeight="cropWidth"
                            :fixed="true"
                            :fixedBox="true"
                            :canMoveBox="false"
                            :centerBox="true"
                            :original="true"
                    ></vue-cropper>
                </div>
                <div class="image-control">
                    <div class="control-btns">
                        <button type="button" @click="changeScale(1)">
                            <i class="fa fa-search-plus"></i>放大
                        </button>
                        <button type="button" @click="changeScale(-1)">
                            <i class="fa fa-search-minus"></i>缩小
                        </button>
                        <button type="button" @click="rotateLeft">
                            <i class="fa fa-rotate-left"></i>向左旋转
                        </button>
                        <button type="button" @click="rotateRight">
                            <i class="fa fa-rotate-right"></i>向右旋转
                        </button>
                    </div>
                    <div class="control-btns">
                        <button type="button" class="close" @click="hide">关闭</button>
                        <button type="button" class="submit" @click="confirmCropper">确认</button>
                    </div>
                </div>
            </div>
        </transition>
    </teleport>
</template>

<script type="text/ecmascript-6">
    import Headbar from '@/components/headbar/headbar';
    import { getAssets } from "@/common/js/functions";

    import { VueCropper } from 'vue-cropper';
    import 'vue-cropper/dist/index.css';

    /* eslint-disable */
    import { openBase64 } from "@/common/js/functions";
    import { DEBUG } from "@/common/js/const";

    export default {
        name: "image-cropper",
        emits: [ 'close', 'finish' ],
        props: {
          imgSrc: {
              type: String,
              default() {
                  return getAssets('alpha-inimages.png')
              }
          }
        },
        data() {
            return {
                showCropper: false
            }
        },
        computed: {
            cropWidth() {
                return Math.floor(document.body.clientWidth) - 20 * 2;
            },
            imgsrc() {
              if (this.imgSrc) {
                  return this.imgSrc;
              } else {
                  console.log(getAssets('alpha-inimages.png'))
                  return getAssets('alpha-inimages.png');
              }
            }
        },
        components: {
            VueCropper,
            Headbar
        },
        methods: {
            show() {
                this.showCropper = true;
            },
            hide() {
                this.showCropper = false;
                this.$emit('close');
            },
            confirmCropper() {
                this.$refs.cropperRef.getCropData((data) => {
                    this.$emit('finish', data);
                    // DEBUG && openBase64(data);
                    this.showCropper = false;
                });
            },
            changeScale(num) {
                num = num || 1;
                this.$refs.cropperRef.changeScale(num);
            },
            rotateLeft() {
                this.$refs.cropperRef.rotateLeft();
            },
            rotateRight() {
                this.$refs.cropperRef.rotateRight();
            }
        }
    }
</script>

<style lang="less" rel="stylesheet/less" scoped>
    @controlBarHeight: 160px;
    .image-cropper {
        position: fixed;
        top: 0;
        left: 0;
        right: 0;
        bottom: 0;
        background-color: var(--color-lightblack);
        z-index: 9999;

        .head-bar{
            color: #fff;
            line-height: var(--height-headbar);
            height: var(--height-headbar);
            text-align: center;
            font-size: 16px;
            background-color: #3f3e3e;
        }

        .cropper-wrapper{
            position: absolute;
            left: 0;
            top: 40px;
            right: 0;
            bottom: @controlBarHeight;
        }

        .image-control{
            position: absolute;
            bottom: 0;
            left: 0;
            right: 0;
            height: @controlBarHeight;
            padding: 10px 0;

            .control-btns{
                display: flex;
                justify-content: center;
                align-items: center;
                height: 70px;

                button{
                    height: 36px;
                    padding: 0 8px;
                    margin-left: 10px;
                    background-color: #2196f3;
                    color: #fff;
                    font-size: 14px;
                    &:first-child{
                        margin-left: 0;
                    }
                    .fa{
                        width: 20px;
                        text-align: center;
                    }
                }
                .submit,.close{
                    width: 40%;
                    height: 45px;
                }
                .submit{
                    background-color: #fc3e5a;
                }
                .close{
                    background-color: #2f2f2f;
                }
            }
        }
    }

    .imageAni-enter-active,
    .imageAni-leave-active {
        transition: all 0.3s;
    }

    .imageAni-enter-from,
    .imageAni-leave-to {
        transform: translate3d(100%, 0, 0);
        opacity: 0;
    }
</style>
