<template>
    <section class="pc-show" v-show="isNotMobile">
        <div class="pc-qrcode">
            <img :src="qrcode">
            <p>请使用手机扫描上方二维码</p>
        </div>
    </section>
    <wait-loading :images="allImages"
                  @loadFinish="imagesLoadFinish"
    ></wait-loading>
    <router-view v-slot="{ Component }">
        <transition name="slideIn" appear>
            <keep-alive>
                <component :is="Component"/>
            </keep-alive>
        </transition>
    </router-view>

</template>

<script>
    import WaitLoading from '@/components/wait-loading/wait-loading';

    import {mapActions, mapMutations} from 'vuex';
    import getSetting from '@/common/js/getSetting.js';
    import {getAssets,getRandomInt} from "@/common/js/functions";
    import wudialogs from '@/common/js/wudialogs';
    import { SCREEN_WIDTH, QR_QDXIN } from "@/common/js/const";
    // import setWxshare from "@/common/js/wxshare_pure";
    import { shareConfig } from "@/common/js/wxshare";

    export default {
        name: 'App',
        components: {
            WaitLoading
        },
        data() {
            return {
                setting: {},
                allImages: []
            }
        },
        computed: {
            isNotMobile() {
                return SCREEN_WIDTH > 560 ? true : false;
            },
            qrcode() {
                const url = window.location.href.split('#')[0];
                return `${QR_QDXIN}?data=${url}`;
            }
        },
        created() {
            getSetting().then(result => {
                this.setting = result;

                document.title = result.title;

                let description = '';
                // 判断描述是否为数组 否则是一个字符串 是数组生成随机描述
                if (Array.isArray(result.description)) {
                    const descRand = getRandomInt(result.description.length - 1);
                    description = result.description[descRand];
                } else {
                    description = result.description;
                }
                document.querySelector('meta[name="description"]').content = description;

                // 设置微信分享
                // setWxshare({
                //     t_pic: result.wxshare_tpic,
                //     t_url: result.wxshare_turl,
                //     t_title: result.title,
                //     t_summ: description
                // });
                shareConfig({
                    wxtitle: result.title,
                    title: result.title,
                    desc: description,
                    imgsrc: result.wxshare_tpic,
                    link: result.wxshare_turl
                });

                this.setSettingData({
                    start: result.start,
                    paster: result.paster.files,
                    textconfig: result.text_config,
                    popbg: result.pop_bg,
                    textdemo: result.text_demo
                });

                this.setAllimages(result);
            }).catch(() => {
                wudialogs.alert('抱歉，配置文件获取失败，请刷新重试');
            });
        },
        methods: {
            setAllimages(result) {
                result.paster.files.forEach((file) => {
                    this.allImages.push(file.has_text);
                    this.allImages.push(file.no_text);
                });
                this.allImages.push(result.start.title);
                this.allImages.push(result.start.main);
                this.allImages.push(result.start.button);
                this.allImages.push(result.start.background);
                // 微信分享图使用的是绝对链接 不要加入加载中
                // this.allImages.push(result.wxshare_tpic);

                let arr = [];
                this.allImages.forEach((item) => {
                    item = getAssets(item);
                    arr.push(item);
                });
                this.allImages = arr;
            },
            imagesLoadFinish() {
                this.setImgsLoaded(true);
            },
            ...mapMutations([
                'setImgsLoaded'
            ]),
            ...mapActions([
                'setSettingData'
            ])
        }
    }
</script>

