<template>
    <transition name="fadeout">
        <section class="loading" v-show="showLoading">
            <div class="loading-inner">
                <div class="load">
                    <div class="skip-loading" @click="hiddenLoading" v-show="showSkipBtn">跳过</div>
                    <p class="load-tips">
                        资源加载中 请稍候
                    </p>
                    <div id="load-growing" class="load-growing"><cite></cite></div>
                    <p class="load-num">0%</p>
                </div>
            </div>
        </section>
    </transition>
</template>

<script type="text/ecmascript-6">
    import LoadImg from "@/common/js/loadimg";
    import {mapGetters,mapMutations,mapActions} from 'vuex';
    import {findInPasters} from "@/common/js/functions";
    import wudialog from '@/common/js/wudialogs';

    let isLoaded = false;

    export default {
        name: "wait-loading",
        emits: [ 'loadFinish' ],
        props: {
            images: {
                type: Array,
                default() {
                    return []
                }
            },
        },
        data() {
            return {
                showLoading: true,
                showSkipBtn: false
            }
        },
        computed: {
            ...mapGetters([
                'pasters'
            ])
        },
        methods: {
            // 用于加载失败的时候，手动隐藏加载层
            hiddenLoading() {
                this.showLoading = false;
                isLoaded = true;
            },
            // 加载大于15%时的事件
            loadGtrTen() {
                window.addEventListener('load_gtr_ten', () => {
                    this.showSkipBtn = true;
                });
            },
            // 监听加载事件的完成
            loadComplete() {
                window.addEventListener('loadover', (res) => {
                    const errorImgs = res.detail.errorImages;
                    if (errorImgs.length > 0) {
                        const handleRes = this.handleErrors(errorImgs);
                        if (!handleRes) {
                            return;
                        }
                    }
                    // 如果loading层已经被隐藏了 那么不做处理
                    if (!this.showLoading) {
                        return;
                    }
                    this.showLoading = !this.showLoading;
                    isLoaded = true;

                    this.$emit('loadFinish');
                });
            },
            // 处理图片加载错误
            handleErrors(errorImgs) {
                // 错误处理结果 如果没有贴纸那么就不要进入start界面
                let handleRes = true;
                errorImgs.forEach((src) => {
                    // 只处理贴纸错误：查看问题图片是否在pasters找到索引
                    const pasterIndex = findInPasters(src, this.pasters);
                    if (pasterIndex >= 0) {
                        this.removePasterItem({
                            pasters: this.pasters,
                            index: pasterIndex
                        });
                        // 判断贴纸是否还有
                        if (this.pasters.length <= 0) {
                            wudialog.alert(
                                '您的资源加载遇到问题，请刷新重试',
                                function () {
                                    window.location.reload();
                                }
                            );
                            handleRes = false;
                        }
                    }
                });
                return handleRes;
            },
            loadInit() {
                // console.log(this.images);
                // 只有图片存在的时候才执行，否则直接发送成功事件
                if (this.images.length > 0) {
                    setTimeout(() => {
                        // console.log('s', this.images);
                        new LoadImg(this.images, 'load-growing');
                    }, 20)
                }
            },
            ...mapMutations([
                'setStart'
            ]),
            ...mapActions([
                'removePasterItem'
            ])
        },
        watch: {
            images(val) {
                if (!isLoaded && val.length > 0) {
                    this.loadInit();
                    this.loadGtrTen();
                    this.loadComplete();
                    // this.showLoading = !this.showLoading;
                }
            }
        }
    }
</script>

<style lang="less" rel="stylesheet/less">

    .loading {
        position: fixed;
        z-index: 9999;
        top: 0;
        right: 0;
        bottom: 0;
        left: 0;
        background: #fff8bd;
    }

    .loading-inner{
        display: flex;
        align-items: center;
        justify-content: center;
        width: 100%;
        height: 100%;
    }
    .load{

        .load-growing{
            width: 40vw;
            margin: 0 auto;
            height: 10px;
            background-color: #fff;
            border-radius: 10px;
            box-shadow: 3px 0 3px rgba(0,0,0,0.1);
            overflow: hidden;
            cite{
                display: block;
                transition: all 0.2s;
                background-color: #DC4242;
                height: 10px;
                width: 0;
            }
        }
        .load-num{
            text-align: center;
            color: #a09322;
            margin-top: 10px;
            font-family: "Arial";
        }
        .load-tips{
            color: #a09322;
            font-size: 12px;
            text-align: center;
            margin-bottom: 10px;
        }
    }

    .skip-loading{
        position: absolute;
        top: -70px;
        left: 0;
        right: 0;
        margin: auto;
        width: 100px;
        height: 32px;
        line-height: 32px;
        text-align: center;
        font-size: 14px;
        border: 1px solid #2196f3;
        color: #2196f3;
        border-radius: 10px;
        animation: fade-in 0.7s both;
        z-index: 99;
    }
</style>
