import { POP_CREATE_STATUS } from "@/common/js/const";

export function setSettingData({ commit }, { start, paster, textconfig, popbg, textdemo  }) {
    commit('setStart', start);
    commit('setPaster', paster);
    commit('setTextConfig', textconfig);
    commit('setPopBg', popbg);
    commit('setTextDemo', textdemo);
}

export function resetData({ commit }) {
    commit('setPhoto', '');
    commit('setPopText', '');
    commit('setPop', '');
    commit('setPopStatus', POP_CREATE_STATUS.donot);
    commit('setPhotoOrigin', '');
    commit('setPasterCurrent', 0);
}

// 删除贴纸项
export function removePasterItem({ commit }, { pasters,index }) {
    let copyPaster = pasters.slice();
    copyPaster.splice(index, 1);
    commit('setPaster', copyPaster);
}
