import { createRouter, createWebHashHistory } from 'vue-router';
import StartPage from '@/views/start-page/start-page';
import HomePage from '@/views/home-page/home-page';
import EditPage from '@/views/edit-page/edit-page';
import CardPage from '@/views/card-page/card-page';


const router = createRouter({
  history: createWebHashHistory(),
  routes: [
    {
      path: '/',
      redirect: '/start'
    },
    {
      path: '/start',
      name: 'start-page',
      component: StartPage
    },
    {
      path: '/home',
      name: 'home-page',
      component: HomePage
    },
    {
      path: '/edit',
      name: 'edit-page',
      component: EditPage
    },
    {
      path: '/card',
      name: 'card-page',
      component: CardPage
    }
  ]
});


export default router;
