const wudialogs = {
    // 初始化 在head中插入样式
    init: function () {
        const style = `
            .wu-dialog{
                position: fixed;
                top: 0;
                left: 0;
                right: 0;
                bottom: 0;
                z-index: 1999999999999999;
            }
            .wu-dialog-msg{
                position: absolute;
                width: 70%;
                left: 0;
                right: 0;
                padding: 15px 10px;
                background-color: rgba(0,0,0,0.8);
                border-radius: 10px;
                margin: auto;
                color: #fff;
                text-align: center;
                font-size: 14px;
                box-shadow: 0 0 5px #000;
                display: none;
                animation: wudialog-fadeUp 0.3s;
            }
            .wu-dialog-ani-fadedown{
                animation: wudialog-fadeDown 0.3s both!important;
            }
            .wu-dialog-flex{
                width: 100%;
                height: 100%;
                display: flex;
                align-items: center;
                justify-content: center;
            }
            .alert-flex{
                background: rgba(0,0,0,0.6);
            }
            .wu-dialog-alert{
                width: 80%;
                background: #fff;
                font-size: 14px;
                border-radius: 5px;
                overflow: hidden;
                animation: wudialog-fadeUp 0.3s;
            }
            .alert-top{
                padding: 40px 20px;
                text-align: center;
            }
            .alert-button{
                width: 100%;
                line-height: 50px;
                height: 50px;
                background: #f2f2f2;
            }
            @keyframes wudialog-fadeUp {
                0%{
                    opacity: 0;
                    transform: translate3d(0, 20px, 0);
                }
                100%{
                    opacity: 1;
                    transform: translate3d(0, 0px, 0);
                }
            }
            @keyframes wudialog-fadeDown {
                0%{
                    opacity: 1;
                    transform: translate3d(0, 0px, 0);
                }
                100%{
                    opacity: 0;
                    transform: translate3d(0, 20px, 0);
                }
            }
        `;
        const styleEl = document.createElement('style');
        styleEl.innerHTML = style;
        styleEl.id = 'wu-dialog-style';
        document.head.appendChild(styleEl);
    },
    msg: function (msg = '') {
        if (!msg) {
            return;
        }
        if (document.getElementById('wu-dialog')) {
            return;
        }
        const wrapper = document.createElement('div');
        wrapper.className = 'wu-dialog';
        wrapper.id = 'wu-dialog';
        const containerHtml = `
            <div class="wu-dialog-flex">
                <div class="wu-dialog-msg" id="wu-dialog-msg">
                    ${msg}
                </div>
            </div>
        `;
        wrapper.innerHTML = containerHtml;
        document.body.appendChild(wrapper);

        const msgEl = document.getElementById('wu-dialog-msg');
        msgEl.style.display = 'block';

        setTimeout(() => {
            msgEl.className = "wu-dialog-msg wu-dialog-ani-fadedown";
            msgEl.addEventListener('animationend', () => {
                wrapper.remove();
            });
        }, 1500);

    },
    alert: function (msg = '', callback = null) {
        if (!msg) {
            return;
        }
        if (document.getElementById('wu-dialog')) {
            return;
        }
        const wrapper = document.createElement('div');
        wrapper.className = 'wu-dialog';
        wrapper.id = 'wu-dialog';
        const containerHtml = `
            <div class="wu-dialog-flex alert-flex">
                <div class="wu-dialog-alert" id="wu-dialog-alert">
                    <div class="alert-top">${msg}</div>
                    <div class="alert-control">
                        <button type="button" class="alert-button" id="wu-alert-button">确定</button>
                    </div>
                </div>
            </div>
        `;
        wrapper.innerHTML = containerHtml;
        document.body.appendChild(wrapper);

        const alertEl = document.getElementById('wu-dialog-alert');
        alertEl.style.display = 'block';

        const alertSure = document.getElementById('wu-alert-button');
        alertSure.addEventListener('click',  () => {
            alertEl.className = "wu-dialog-alert wu-dialog-ani-fadedown";
            alertEl.addEventListener('animationend', () => {
                wrapper.remove();
                callback && callback();
            });
        });
    }
};

export default wudialogs;
