import wx from 'weixin-js-sdk';
import axios from 'axios';

const WXSHARE_DEBUG = window.setting.wx_share_debug || false;

export function shareConfig(obj) {
  // 获取除了#号之前的链接，注意传入进行转义也要在ajax函数中进行，不能在外部就进行转义
  let baseUrl = window.location.href.split('#')[0];
  // 默认的分享配置
  let baseObj = {
    // 浏览器的title
    wxtitle: '信网资讯',
    // 分享的title
    title: '信网-青岛第一新闻网站',
    // 分享的描述
    desc: '青岛第一网站',
    // 分享的图片
    imgsrc: 'http://m.qdxin.cn/img/logofen170309.png',
    // 分享的链接
    link: baseUrl
  };
  obj.desc = setDesc(obj.desc);
  // 合并传进来的参数给obj
  obj = Object.assign(baseObj, obj);

  // console.log(obj.wxtitle)
  // 设置标题
  // document.title = obj.wxtitle;

  // 请求的地址获取
  let ajaxUrl = setAjaxUrl();

  let wxShareData = {
    "title": obj.title,
    "desc": obj.desc,
    "link": obj.link,
    "imgUrl": obj.imgsrc,
  };
  // console.log(ajaxUrl)
  axios.get(ajaxUrl, {
    // 在地址上拼接字符串，后台要求的格式
    params: {
      u: baseUrl
    }
  }).then((res) => {
    let json1 = res.data;
    let json2 = {
      debug: WXSHARE_DEBUG,
      jsApiList: ['checkJsApi','onMenuShareTimeline','onMenuShareAppMessage','onMenuShareQQ','onMenuShareWeibo','updateAppMessageShareData','updateTimelineShareData','previewImage','chooseImage','openLocation','getLocation','scanQRCode','hideMenuItems','showMenuItems','closeWindow']
    };
    WXSHARE_DEBUG && console.log(res);
    var wxcfg = Object.assign({}, json1, json2);
    wx.config(wxcfg);

    wx.ready(function(){
      wx.checkJsApi({
        jsApiList: ['onMenuShareAppMessage'],
        success: function() {
          wx.onMenuShareAppMessage(wxShareData);
          wx.onMenuShareTimeline(wxShareData);
          wx.onMenuShareQQ(wxShareData);
          wx.onMenuShareWeibo(wxShareData);
        }
      });
      if( typeof wx.updateAppMessageShareData == 'function' ) {
        wx.updateAppMessageShareData(wxShareData);
        wx.updateTimelineShareData(wxShareData);
      }
    });

  }).catch((err) => {
    console.log(err)
  });


  wx.ready(function () {
    wx.checkJsApi({
      jsApiList: ['onMenuShareAppMessage'],
      success: function () {
        wx.onMenuShareAppMessage(wxShareData);
        wx.onMenuShareTimeline(wxShareData);
        wx.onMenuShareQQ(wxShareData);
        wx.onMenuShareWeibo(wxShareData);
      }
    });
    if (typeof wx.updateAppMessageShareData == 'function') {
      wx.updateAppMessageShareData(wxShareData);
      wx.updateTimelineShareData(wxShareData);
    }
  });
}

// 设置描述
let setDesc = function (desc) {
  // 控制120个字符长度
  return desc.substr(0, 120);
}

// 设置请求的地址 会根据不同域名请求不同路径下的jssdk_vars_p.php文件
let setAjaxUrl = function () {
  let a_hn = document.location.host.split('.qdxin.cn');
  let hn = a_hn[0];
  let getUrl = '';
  if(hn=='www'||hn=='m'||hn=='club') {
    getUrl = '//mp.qdxin.cn/qdxw/jssdk_vars_p.php';
  }
  else {
    getUrl = '//mp.qdxin.cn/xwcm/jssdk_vars_p.php';
  }
  // 这里不能固定指定http有可能会是https
  return getUrl;
}

