/* eslint-disable */
const sleep = (timeout = 1000)=>new Promise((resolve)=>{
  setTimeout(resolve, timeout);
});

const LoadImg = (function() {
  // 对于大于10%的时候是否已经抛出事件
  let GTR_ten_percent = false;

  const Load = function(urls, progressId) {
    this.urls = urls;
    this.bar = document.getElementById(progressId);
    this.progress = this.bar.getElementsByTagName('cite')[0];
    this.progressPercent = this.bar.nextElementSibling;
    this.imgNumbers = urls.length;
    this.loadImgNumbers = 0;
    // 用于存储加载遇到错误的图片地址
    this.errorImages = [];
    // console.log(this.progressPercent)
    this.init();
  };

  Load.prototype = {
    loading(self) {
      self.loadImgNumbers++;
      const percent = parseInt((self.loadImgNumbers / self.imgNumbers) * 100) + '%';
      self.progress.style.width = percent;
      self.progressPercent.innerHTML = percent;

      // 当没没有发送大于15的事件
      if (!GTR_ten_percent &&
          parseInt(percent) > 15
      ) {
        let load_gtr_ten = new CustomEvent('load_gtr_ten', {
          // 自定义事件携带的参数
          detail : {
            title: '加载百分比大于10%了'
          }
        });
        // 在window上抛出事件
        if(window.dispatchEvent) {
          window.dispatchEvent(load_gtr_ten);
        } else {
          window.fireEvent(load_gtr_ten);
        }
        GTR_ten_percent = true;
      }

      // 加载完成触发自定义事件
      if (self.loadImgNumbers === self.imgNumbers) {
        let loadOver = new CustomEvent('loadover', {
          // 自定义事件携带的参数
          detail : {
            message: 'load ok',
            errorImages: self.errorImages
          }
        });
        // 随后在对应的元素上显示的触发该事件
        if(window.dispatchEvent) {
          window.dispatchEvent(loadOver);
        } else {
          window.fireEvent(loadOver);
        }
      }
    },
    load: function(self, src) {
      const obj = new Image();
      obj.src = src;
      // 图片加载成功
      obj.onload = () => {
        self.loading(self);
      };
      // 加载成功 end

      // 图片加载失败 无论加载成功与失败都算进度
      obj.onerror = () => {
        // 加载失败的话添加失败的src
        self.errorImages.push(src);
        self.loading(self);
      }
    },
    init: function() {
      const self = this;

      let timer = async(timeout) => {
        for(let i = 0; i < timeout; i++) {
          // 暂停循环，每次间隔一秒
          // await sleep(100);
          await sleep(50);
          // 当stop值是ture的时候中断加载
          self.load(self, self.urls[i]);
        }
      };

      timer(this.imgNumbers);
    }
  };

  return Load;
})();

export default LoadImg;
