<template>
    <teleport to="body">
        <transition name="fadeDown">
            <section class="full-screen-img" v-show="showFull">
                <div class="img-box">
                    <img :src="imgsrc">
                </div>
                <div class="bottom">
                    <p class="img-tips">请长按图片下载到本地相册</p>
                    <div class="close" @click="close">
                        <button type="button" class="close-button">
                            <i class="fa fa-remove"></i>
                        </button>
                    </div>
                </div>
            </section>
        </transition>
    </teleport>
</template>

<script type="text/ecmascript-6">
    export default {
        name: "full-screen-img",
        props: {
            imgsrc: {
                type: String,
                default() {
                    return '';
                }
            }
        },
        data() {
            return {
                showFull: false
            }
        },
        methods: {
            open() {
                this.showFull = true;
            },
            close() {
                this.showFull = false;
            }
        }
    }
</script>

<style lang="less" rel="stylesheet/less" scoped>
    @bottomHeight: 130px;
    @tipsHeight: 30px;
    .full-screen-img {
        position: fixed;
        left: 0;
        right: 0;
        top: 0;
        bottom: 0;
        background-color: rgba(0,0,0,0.9);

        .img-box{
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: @bottomHeight;
            padding-top: 20px;
            text-align: center;
            background: url("loading-pc.gif") center center no-repeat;

            img{
                height: 100%;
                width: auto;
                display: inline-block;
            }
        }

        .bottom{
            position: absolute;
            bottom: 0;
            left: 0;
            right: 0;

            .img-tips{
                color: #fff;
                text-align: center;
                font-size: 12px;
                line-height: @tipsHeight;
                height: @tipsHeight;
            }
        }
        .close{
            color: #fff;
            height: @bottomHeight - @tipsHeight;
            line-height: @bottomHeight - @tipsHeight - 15px;
            text-align: center;
            font-size: 28px;
            text-align: center;
        }
        .close-button{
            border-radius: 50%;
            border: 1px solid;
            color: #fff;
            width: 50px;
            height: 50px;
            font-size: 24px;
            background: transparent;
            display: inline-flex;
            justify-content: center;
            align-items: center;
        }

    }
</style>
