import {PUBLIC_PATH, ASSETS_PATH, ID, TIME_STRAMP} from './const';

export function getQueryStringArgs() {
    var qs = (location.search.length > 0 ? location.search.substring(1) : ""),
        args = {},
        //get individual items
        items = qs.length ? qs.split("&") : [],
        item = null,
        name = null,
        value = null,
        i = 0,
        len = items.length;

    for (i = 0; i < len; i++) {
        item = items[i].split("=");
        name = decodeURIComponent(item[0]);
        value = decodeURIComponent(item[1]);

        if (name.length) {
            args[name] = value;
        }
    }

    return args;
}

export function request(url, method = 'get', data = '') {
    return new Promise((resolve, reject) => {
        const ajax = new XMLHttpRequest();
        try {
            if (method.toLowerCase() == 'get') {
                if (data) {
                    url = `${url + '?'}${data}`;
                }
                ajax.open(method, url);
                ajax.send();
            }
        } catch (e) {
            console.log(e)
            reject(false);
        }

        ajax.onreadystatechange = function () {
            // 0 未初始化状态 1:准备发送 2：已经发送 3正在接收 4：完成
            if (ajax.readyState === 4 && ajax.status === 200) {
                const result = JSON.parse(ajax.responseText);
                resolve(result);
            }
        };
        ajax.onerror = function () {
            reject(false);
        }
    });
}

export function getAssets(file) {
    let imgsrc = '';
    if (!file) {
        imgsrc = `${PUBLIC_PATH}images/alpha.png`;
    } else {
        // 如果文件名中含有inimages 那么就从images文件夹中寻找
        if (file.indexOf('inimages') > -1) {
            imgsrc = `${PUBLIC_PATH}images/${file}`;
        } else {
            imgsrc = `${PUBLIC_PATH}${ASSETS_PATH}/${ID}/${file}`;
        }
    }
    if (TIME_STRAMP) {
        imgsrc = `${imgsrc}?t=${TIME_STRAMP}`;
    }
    return imgsrc;
}

export function getRandomInt(max) {
    // Math.random() 0-1之间值 但不包含1
    return Math.floor(Math.random() * (max + 1))
}


export function readImage2Base64(files) {
    return new Promise((resolve) => {
        //判断浏览器是否支持filereader
        if (typeof FileReader == 'undefined') {
            window.alert('抱歉，你的浏览器不支持 FileReader');
            resolve(false);
        }
        const file = files[0];
        //判断获取的是否为图片文件
        if (!/image\/\w+/.test(file.type)) {
            window.alert("文件必须为图像文件");
            resolve(false);
        }
        let reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = function () {
            const base64 = this.result;
            resolve(base64);
        }
    });
}


export function openBase64(base64) {
    if (!base64) {
        window.alert('没有base64数据');
        return;
    }
    const img = new window.Image();
    img.src = base64;

    const newWin = window.open('');
    // 如果浏览器拦截了窗口打开 那么window.open就会返回null
    if (!newWin) {
        window.alert('弹出窗口被浏览器拦截了，请查看地址栏右侧有无相关设置！结果已在控制台打印');
        console.log(base64);
    }
    newWin.document.body.style.background = '#000';
    newWin.document.body.style.textAlign = 'center';
    newWin.document.body.appendChild(img);
    newWin.document.title = '图片预览';
    newWin.document.close();
}

export function isImageLoaded(img) {
    // 如果图片的complete属性为true且自然宽度不等于0时表示图片已加载完成
    return img.complete && (img.naturalWidth > 0);
}

export function imgLoaded(imgEl) {
    return new Promise((resolve, reject) => {
        imgEl.onload = resolve(true);
        imgEl.onerror = reject(false);
    });
}

// 查看图片src是否在start中，在的话就用透明图片替换
export function findInStartData(src, startData) {
    let result = {};
    for (let key in startData) {
        if (src.indexOf(startData[key]) > -1) {
            result[key] = 'alpha-inimages.png';
        } else {
            result[key] = startData[key];
        }
    }
    return result;
}

export function findInPasters(src, pasters) {
    return pasters.findIndex((paster) => {
        // console.log(src, paster, src.indexOf(paster.has_text) > -1)
        return src.indexOf(paster.has_text) > -1 || src.indexOf(paster.no_text) > -1;
    })
}
