<template>
    <teleport to="body">
        <transition name="slideIn">
            <div class="pop-textarea" v-show="showTextarea">
                <headbar :text="headtext"
                         @click="debugInsertText"
                ></headbar>
                <div class="textarea-wrapper">
                    <textarea :maxlength="maxlength"
                              :rows="textareaRows"
                              placeholder="请填写您要展示的文字内容"
                              @focus="toggleTextareaFocus(true)"
                              @blur="toggleTextareaFocus(false)"
                              v-model="textContent"
                    ></textarea>
                    <div class="tips">
                        <div class="clear-text" @click="clearTextarea">
                            <i class="fa fa-trash-o"></i> 清空
                        </div>
                        <p>您还可以输入 {{ residueTextNum }} 字</p>
                    </div>
                    <div class="submit" :class="{'show-create': textDemo.length > 0}">
                        <button type="button" class="submit-btn" @click="submit">
                            完 成
                        </button>
                        <button type="button" class="create-btn" @click="createRandDemo">
                            随机生成
                        </button>
                    </div>
                </div>
                <div class="close" :class="{'focus-text': focusText}">
                    <button type="button" @click="close">
                        <i class="fa fa-remove"></i>
                    </button>
                </div>
            </div>
        </transition>
    </teleport>
</template>

<script type="text/ecmascript-6">
    import Headbar from '@/components/headbar/headbar';
    import { DEBUG, SCREEN_HEIGHT, IS_IOS } from "@/common/js/const";
    import { getRandomInt } from "@/common/js/functions";

    const DEMO_TEXT = '在这充满喜庆的春节里，愿你的生活如诗如画，美不胜收。愿你在新的一年里，事业有成，蒸蒸日上，生活更上一层楼。祝你春节快乐!';

    export default {
        name: "pop-textarea",
        emits: [ 'submit' ],
        props: {
            headtext: {
                type: String,
                default() {
                    return '编辑您的文字内容'
                }
            },
            maxlength: {
                type: Number,
                default() {
                    return 30
                }
            },
            textDemo: {
                type: Array,
                default() {
                    return []
                }
            }
        },
        computed: {
          // 根据maxlength确定输入框的行数
          textareaRows() {
              const rows = Math.ceil(this.maxlength / 10);
              return rows < 8 ? 8 : rows;
          },
            residueTextNum() {
                const residue = this.maxlength - this.textContent.length;
                return residue > 0 ? residue : 0;
            }
        },
        data() {
            return {
                showTextarea: false,
                textContent: '',
                focusText: false
            }
        },
        mounted() {
            // 当唤起键盘时 屏幕尺寸会发生改变 这里只针对安卓 苹果虚拟键盘调起的时候不触发屏幕变化事件
            window.onresize = () => {
                if (IS_IOS) {
                    return;
                }
                const resizeHeight = document.body.clientHeight;
                // 当安卓端键盘调上来后document.body.clientHeight和window.innerHeight值一致
                // console.log(resizeHeight, window.innerHeight);
                if (resizeHeight < SCREEN_HEIGHT) {
                    // 如果变化后的高度比之前小 代表虚拟键盘展开了 那么代表需要隐藏按钮
                    this.focusText = true;
                } else {
                    // 如果变化后的高度>=之前 代表虚拟键盘关闭了 但是此时失焦与否不确定
                    this.focusText = false;
                }
            }
        },
        methods: {
            clearTextarea() {
                this.textContent = '';
            },
            toggleTextareaFocus(focus) {
                if (IS_IOS) {
                    return;
                }
              this.focusText = focus;
            },
            debugInsertText() {
                if (DEBUG) {
                    this.textContent = DEMO_TEXT.substr(0, this.maxlength);
                }
            },
            open(content = '') {
                this.textContent = content;
                this.showTextarea = true;
            },
            close() {
                this.showTextarea = false;
            },
            createRandDemo() {
                if (this.textDemo.length <= 0) {
                    return;
                }
                let copyTextdemo = this.textDemo.slice();
                console.log(copyTextdemo);
                // 找到是否有重复的
                const nowCurrent = copyTextdemo.findIndex((value) => {
                   return value == this.textContent;
                });
                // 如果大于0就从数组中将重复的删除
                if (nowCurrent > 0) {
                    copyTextdemo.splice(nowCurrent, 1);
                    // console.log(copyTextdemo);
                }
                const rand = getRandomInt(copyTextdemo.length - 1);
                this.textContent = copyTextdemo[rand];
            },
            submit() {
                this.$emit('submit', this.textContent);
                this.close();
            }
        },
        components: {
            Headbar
        }
    }
</script>

<style lang="less" rel="stylesheet/less" scoped>
    .pop-textarea {
        position: fixed;
        left: 0;
        top: 0;
        right: 0;
        bottom: 0;
        background-color: var(--color-deepgray);
        z-index: 999999;

        .textarea-wrapper {
            padding: 20px;

            textarea {
                width: 100%;
                border-radius: 10px;
                padding: 10px;
                line-height: 24px;
            }

            .tips {
                height: 50px;
                align-items: center;
                justify-content: space-between;
                display: flex;

                .clear-text{
                    color: #d2d2cf;
                    font-size: 14px;
                }
                p {
                    color: #fff;
                    font-size: 14px;
                    text-align: right;
                }
            }

            .submit {
                text-align: center;
                padding-top: 20px;

                .submit-btn,
                .create-btn {
                    color: #fff;
                    line-height: 46px;
                    width: 50%;
                    font-size: 16px;
                }
                .submit-btn {
                    background-color: var(--color-btnblue);
                }
                .create-btn{
                    background-color: var(--color-btnred);
                    display: none;
                }

                &.show-create{
                    .submit-btn{
                        width: 40%;
                        margin-right: 20px;
                    }
                    .create-btn{
                        width: 40%;
                        display: inline-block;
                    }
                }
            }
        }

        .close {
            position: absolute;
            left: 0;
            right: 0;
            bottom: 0;
            padding: 0 0 15vh;
            text-align: center;

            &.focus-text{
                opacity: 0;
            }

            button {
               border-radius: 50%;
                width: 50px;
                height: 50px;
                background-color: transparent;
                color: #fff;
                font-size: 24px;
                border: 1px solid;
                text-align: center;
                display: inline-flex;
                justify-content: center;
                align-items: center;
            }
        }
    }
</style>
