import { getQueryStringArgs, request } from "./functions";
import { PUBLIC_PATH, ASSETS_PATH  } from './const';

const timestamp = window.setting.data_timestramp || '';

export default function () {
    return new Promise((resolve, reject) => {
        const querys = getQueryStringArgs();
        const QUERY_ID = querys.id ? querys.id : 'spring';
        const suffix = timestamp ? `?t=${timestamp}` : '';
        const url = `${PUBLIC_PATH}${ASSETS_PATH}/${QUERY_ID}/data.json${suffix}`;

        request(url).then((res) => {
           // console.log(res);
           resolve(res);
        }).catch(() => {
            reject(false);
        });
    });

}
