<template>
    <transition name="slideIn">
        <div class="start-page"
             :class="{'loaded': imgsLoaded == true}"
             :style="bgCls"
             v-show="showStart"
        >
            <div class="top">
                <img :src="topSrc" @error="errorImgLoad(1, $event)">
            </div>
            <div class="middle">
                <img :src="mainSrc" @error="errorImgLoad(1, $event)">
            </div>
            <div class="bottom" @click="closeStart">
                <img :src="bottomSrc" @error="errorImgLoad(2, $event)">
            </div>
        </div>
    </transition>
</template>

<script type="text/ecmascript-6">
    import { getAssets } from "@/common/js/functions";
    import { mapGetters } from 'vuex';
    import { PUBLIC_PATH } from "@/common/js/const";

    export default {
        name: "start-page",
        props: {},
        data() {
          return {
              showStart: true
          }
        },
        computed: {
            bgCls() {
                const src = getAssets(this.startData.background);
                return `background-image: url('${src}')`;
            },
            topSrc() {
                const src = getAssets(this.startData.title);
                return src;
            },
            bottomSrc() {
                const src = getAssets(this.startData.button);
                return src;
            },
            mainSrc() {
                const src = getAssets(this.startData.main);
                return src;
            },
            ...mapGetters([
                'startData',
                'imgsLoaded'
            ])
        },
        methods: {
            // 图片加载失败就替换为个透明图
            errorImgLoad(type, event) {
                this.$nextTick(() => {
                    switch (type) {
                        case 1:
                            event.target.src = `${PUBLIC_PATH}images/alpha.png`;
                            break;
                        case 2:
                            event.target.src = `${PUBLIC_PATH}images/default-start-btn.png`;
                            break;
                    }
                });
            },
            closeStart() {
                this.$router.replace({
                    path: '/home'
                });
            }
        }
    }
</script>

<style lang="less" rel="stylesheet/less" scoped>
    .start-page {
        position: fixed;
        left: 0;
        right: 0;
        top: 0;
        bottom: 0;
        background-color: #eeeeee;
        background-size: cover;
        background-repeat: no-repeat;
        background-position: center center;
        z-index: 100;

        &.loaded{
            .top{
                animation: bounceInDown;
                animation-duration: 1s;
                animation-delay: 0.2s;
                animation-fill-mode: both;
            }
            .middle{
                animation: bounceIn;
                animation-duration: 1s;
                animation-delay: 0.6s;
                animation-fill-mode: both;
            }
            .bottom{
                animation: bounceInUp;
                animation-duration: 1s;
                animation-delay: 0.8s;
                animation-fill-mode: both;
            }
        }

        .middle{
            width: 100%;
            height: 100%;
            display: flex;
            align-items: center;
            justify-content: center;
            img{
                width: 90%;
                height: auto;
                margin-bottom: -50px;
            }
        }

        .top{
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            padding: 20px 10vw;
            z-index: 1;
        }
        .bottom{
            position: absolute;
            bottom: 0;
            left: 0;
            right: 0;
            padding: 0 6vw 5vh 6vw;
        }
    }
</style>
