const mutations = {
    setStart(state, startData) {
        state.start = Object.assign(state.start, startData);
    },
    setPaster(state, pasterData) {
        state.paster = pasterData;
    },
    setPhotoOrigin(state, base64) {
        state.base64_origin_photo = base64;
    },
    // 存储拍照或者上传的图像
    setPhoto(state, base64) {
        state.base64_photo = base64;
    },
    // 存储海报
    setPop(state, base64) {
        state.base64_pop = base64;
    },
    // 海报上的字体
    setPopText(state, text) {
        state.pop_text = text;
    },
    setTextConfig(state, config) {
        state.text_config = Object.assign(state.text_config, config);
    },
    setPopBg(state, popObj) {
        state.pop_bg = Object.assign(state.pop_bg, popObj);
    },
    setPopStatus(state, status) {
        state.pop_status = status;
    },
    setImgsLoaded(state, status) {
        state.imgsLoadFinish = status;
    },
    setPasterCurrent(state, current) {
        state.paster_current = current;
    },
    setTextDemo(state, demo) {
        state.text_demo = demo
    }
};

export default mutations
