<template>
    <section class="edit-page">
        <div class="edit-wrapper">
            <div class="edit-flex">
                <div class="edit-inner">
                    <div class="photo-box"
                         id="photo-box"
                    >
                        <div class="photo-box-inner"
                             :style="photoStyle"
                        >
                            <img :src="photoPaster" class="photo-paster" ref="photoPasterRef">
                            <img :src="base64PhotoOrigin"
                                 class="photo-origin"
                                 ref="photoBase64Ref"
                                 :style="photoOriginStyle"
                            >
                        </div>
                    </div>
                    <div class="bottom">
                        <div class="select-row">
                            <p class="row-p">模板</p>
                            <div class="row-content paster-ul-wrapper" id="paster-ul-wrapper">
                                <ul class="paster-ul"
                                    :style="pasterUlStyle"
                                    ref="pasterUlRef"
                                >
                                    <li v-for="(paster, pindex) in pasters"
                                        :key="pindex"
                                        :class="{'active': pindex == pasterCurrent}"
                                        @click="selectPaster(pindex)"
                                    >
                                        <div class="paster-inner">
                                            <img :src="getPasterSrc(paster)">
                                        </div>
                                    </li>
                                </ul>
                            </div>
                        </div>
                        <div class="select-row" v-if="textConfig.text_support">
                            <p class="row-p">{{ textConfig.text_title }}</p>
                            <div class="row-content">
                                <div class="message-btn-box"
                                     v-show="!popText"
                                >
                                    <button type="button" class="message-button" @click="openTextarea">
                                        {{ textConfig.text_btn }}
                                    </button>
                                    <small>（可选）</small>
                                </div>
                                <div class="message-show" v-show="popText">
                                    <div class="left">
                                        <div class="left-inner" ref="messageWrapperRef">
                                            <p @click="openTextarea">{{ popText }}</p>
                                        </div>
                                    </div>
                                    <div class="right" @click="openTextarea">
                                        <i class="fa fa-edit"></i>
                                    </div>
                                </div>
                            </div>
                        </div>
                        <div class="control-btns">
                            <button type="button" class="close" @click="gohome">
                                <i class="fa fa-camera"></i> 重新拍摄
                            </button>
                            <button type="button" class="next" @click="synthesisPhoto">
                                <i class="fa fa-film"></i> 生成海报
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        </div>
        <pop-textarea :headtext="textConfig.text_texteare_head"
                      :maxlength="textConfig.text_max_length"
                      :textDemo="textDemo"
                      @submit="submitTextarea"
                      ref="popTextearaRef"
        ></pop-textarea>
        <waiting :tips="'请稍候...'"></waiting>
    </section>
</template>

<script type="text/ecmascript-6">
    import Headbar from '@/components/headbar/headbar';
    import BScroll from '@better-scroll/core';
    import Scrollbar from '@better-scroll/scroll-bar';
    import PopTextarea from '@/components/pop-textarea/pop-textarea';
    import Waiting from '@/components/waiting/waiting';
    import wudialogs from '@/common/js/wudialogs';

    /* eslint-disable */
    import {SCREEN_WIDTH, PUBLIC_PATH, DEBUG, POP_CREATE_STATUS,  POP_WIDTH, POP_HEIGHT } from "@/common/js/const";
    import {mapGetters, mapMutations} from 'vuex';
    /* eslint-disable */
    import {getAssets, openBase64, isImageLoaded} from "@/common/js/functions";
    import {screenShots} from "@/common/js/html2image";
    import {SCREEN_HEIGHT} from "../../common/js/const";

    BScroll.use(Scrollbar);

    // 底部三行的高度的和
    const BOTTOM_HEIGHT = 240;
    // 图片盒子上下的外边距
    const PHOTOBX_PADDING = 15;

    export default {
        name: "edit-page",
        components: {
            Headbar,
            PopTextarea,
            Waiting
        },
        mounted() {},
        // 添加路由钩子函数 在进入之前执行
        beforeRouteEnter(to, from, next) {
            // console.log(next)
            next(vm => {
                // 进入路由后，滚动岛对应的贴图元素
                if (vm.pasterScroll) {
                    const pasterUl = this.$refs.pasterUlRef;
                    const currentPasterLi = pasterUl.querySelectorAll('li')[this.pasterCurrent];
                    vm.pasterScroll.scrollToElement(currentPasterLi, 300)
                }
            });
        },
        data() {
            return {}
        },
        computed: {
            photoStyle() {
                const innerHeight = SCREEN_HEIGHT - BOTTOM_HEIGHT - PHOTOBX_PADDING * 2;
                const innerWidth = Math.floor((POP_WIDTH / POP_HEIGHT) * innerHeight);
                return `width: ${innerWidth}px;height: ${innerHeight}px;opacity: 1;`;
            },
            photoOriginStyle() {
                const innerHeight = SCREEN_HEIGHT - BOTTOM_HEIGHT - PHOTOBX_PADDING * 2;
                const phototop = this.popBg.photo_css.top;
                const photoleft = this.popBg.photo_css.left;
                const photowidth = this.popBg.photo_css.width;
                const top = Math.floor((phototop / POP_HEIGHT) * innerHeight);
                const left =  Math.floor((photoleft / POP_HEIGHT) * innerHeight);
                const width = Math.floor((photowidth / POP_HEIGHT) * innerHeight);
                return `width: ${width}px;top: ${top}px;left: ${left}px`;
            },
            pasterUlStyle() {
                const width = 50 + 10;
                const len = this.pasters.length;
                const outWidth = width * len;
                return `width: ${outWidth}px`;
            },
            photoPaster() {
                let imgsrc = '';
                if (this.pasters[this.pasterCurrent]) {
                    imgsrc = this.pasters[this.pasterCurrent].no_text;
                    imgsrc = getAssets(imgsrc);
                } else {
                    imgsrc = `${PUBLIC_PATH}images/alpha.png`;
                }
                return imgsrc;
            },
            ...mapGetters([
                'base64PhotoOrigin',
                'base64Photo',
                'pasters',
                'textConfig',
                'popText',
                'pasterCurrent',
                'popBg',
                'textDemo'
            ])
        },
        methods: {
            // 生成海报
            synthesisPhoto() {
                if (!this.base64PhotoOrigin) {
                    wudialogs.alert('抱歉，请先上传或者拍摄一张图片');
                    return;
                }
                const pasterLoaded = isImageLoaded(this.$refs.photoPasterRef);
                const photoLoaded = isImageLoaded(this.$refs.photoBase64Ref);
                if (!pasterLoaded || !photoLoaded) {
                    wudialogs.alert('抱歉，请等待贴纸和图像加载完毕后再尝试');
                    return;
                }
                // 将原本图片赋值给base64_photo
                this.setPhoto(this.base64PhotoOrigin);
                this.gocard();
            },
            gocard() {
                this.$router.replace({
                    path: '/card'
                });
            },
            gohome() {
                // 设置拍摄为空 会监听并自动返回
                this.setPhotoOrigin('');
            },
            submitTextarea(text) {
                this.setPopText(text);
            },
            openTextarea() {
                this.$refs.popTextearaRef.open(this.popText);
            },
            getPasterSrc(file) {
                const paster = file.thumb ? file.thumb : file.no_text;
                const imgsrc = getAssets(paster);
                return imgsrc;
            },
            initEffectScroll() {
                if (this.pasterScroll) {
                    this.pasterScroll.refresh();
                } else {
                    let pasterWrapper = document.getElementById('paster-ul-wrapper');
                    this.pasterScroll = new BScroll(pasterWrapper, {
                        scrollX: true,
                        scrollY: false,
                        click: true,
                        scrollbar: {
                            fade: false
                        }
                    });
                }
            },
            selectPaster(pindex) {
                this.setPasterCurrent(pindex);
                const pasterUl = this.$refs.pasterUlRef;
                const currentPasterLi = pasterUl.querySelectorAll('li')[pindex];
                this.pasterScroll.scrollToElement(currentPasterLi, 300, true)
            },
            ...mapMutations([
                'setPopText',
                'setPhoto',
                'setPopStatus',
                'setPhotoOrigin',
                'setPasterCurrent'
            ])
        },
        watch: {
            popText(newval) {
                if (newval) {
                    this.$nextTick(() => {
                        if (this.messageScroll) {
                            this.messageScroll.refresh();
                        } else {
                            const messageWrapper = this.$refs.messageWrapperRef;
                            this.messageScroll = new BScroll(messageWrapper, {
                                scrollY: true,
                                click: true,
                                scrollbar: {
                                    fade: false
                                }
                            });
                        }
                    });
                }
            },
            pasters: {
                handler(newval) {
                    if (newval.length > 1) {
                        this.$nextTick(() => {
                            this.initEffectScroll();
                        });
                    }
                },
                immediate: true,
                deep: true
            },
            base64PhotoOrigin: {
                handler(newVal) {
                    if (!newVal) {
                        this.$router.replace({
                            path: '/home'
                        });
                        this.setPopStatus(POP_CREATE_STATUS.donot);
                    }
                },
                immediate: true
            }
        }
    }
</script>

<style lang="less" rel="stylesheet/less" scoped>
    .edit-page {
        position: fixed;
        left: 0;
        top: 0;
        right: 0;
        bottom: 0;
        background-color: var(--color-deepgray);
        overflow: auto;

        .edit-wrapper {
            position: absolute;
            left: 0;
            /*top: var(--height-headbar);*/
            top: 0;
            right: 0;
            bottom: 0;

            .edit-flex {
                width: 100%;
                height: 100%;
                display: flex;
                align-items: center;
                flex-wrap: wrap;
            }
        }

        .photo-box {
            padding: 15px 20px;
            background: #4a4a4a;
            width: 100%;

            .photo-box-inner{
                background: #3d3d3d url('icon-picture.svg') center center no-repeat;
                background-size: 20% auto;
                position: relative;
                height: 100%;
                min-width: 100px;
                margin: 0px auto;
            }

            .photo-paster {
                position: relative;
                z-index: 2;
            }
            .photo-origin{
                position: absolute;
                z-index: 1;
            }
        }

        .edit-inner {
            width: 100%;
            height: 100%;
            display: flex;
            /* 指定了主轴方向为垂直方向（即竖直） */
            flex-direction: column;

            .bottom{
                flex: 0 0 240px;
            }
            .photo-box{
                flex: 1;
            }
        }

        .select-row {
            display: flex;
            align-items: center;
            padding: 10px 20px;
            width: 100%;

            .row-content {
                flex: 1;
            }

            .row-p {
                flex: 0 0 50px;
                height: 50px;
                line-height: 50px;
                font-size: 14px;
                color: #fff;
            }
        }

        .paster-ul-wrapper {
            height: 50px;
            overflow: hidden;
            position: relative;
        }

        .paster-ul {
            display: flex;

            li {
                display: inline-block;
                width: 50px;
                height: 50px;
                overflow: hidden;
                background: #fff;
                padding: 3px;
                border-radius: 5px;
                margin-left: 10px;

                .paster-inner{
                    width: 100%;
                    height: 100%;
                    overflow: hidden;
                }

                &:first-child {
                    margin-left: 0;
                }

                &.active {
                    opacity: 0.5;
                }
            }
        }

        .message-btn-box {
            height: 50px;
            display: flex;
            align-items: center;
            color: #fff;

            .message-button {
                background-color: var(--color-btnblue);
                color: #fff;
                line-height: 40px;
                padding: 0 30px;
                font-size: 14px;
            }

            small {
                font-size: 12px;
                display: inline-block;
                padding-left: 5px;
            }
        }

        .message-show {
            display: flex;
            background-color: #3e3e3e;
            padding: 10px 0 10px 0px;
            align-items: center;
            border-radius: 5px;

            .left {
                color: #fff;
                flex: 1;
                overflow: hidden;
                padding-left: 10px;

                .left-inner {
                    height: 40px;
                    position: relative;
                }

                p {
                    padding-right: 10px;
                    font-size: 14px;
                    line-height: 18px;
                }
            }

            .right {
                flex: 0 0 40px;
                height: 100%;
                line-height: 100%;
                font-size: 20px;
                text-align: center;
                color: #9c9c9c;
            }
        }

        .control-btns {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 20px;

            button {
                width: 48%;
                height: 50px;
                line-height: 50px;
                color: #fff;
                font-size: 14px;

                &.next {
                    background-color: var(--color-btnred);
                }

                &.close {
                    background-color: var(--color-deepgray-l);
                }

                .fa {
                    display: inline-block;
                    width: 20px;
                }
            }
        }
    }
</style>
