<template>
    <section class="home-page">
        <headbar text="上传或拍摄您的照片"></headbar>
        <div class="home">
            <div class="home-inner">
                <div class="home-select">
                    <div class="select-show"></div>
                    <div class="select-btns">
                        <label for="upload-input" class="btn-upload">
                            <i class="fa fa-upload"></i> 相册上传
                            <input type="file"
                                   accept="image/*"
                                   class="avatar-input"
                                   id="upload-input"
                                   @change="uploadPhoto($event)"
                            >
                        </label>

                        <button type="button"
                                class="btn-photo"
                                @click="openCamera"
                        >
                            <i class="fa fa-camera"></i> 拍摄照片
                        </button>
                    </div>
                </div>
            </div>
            <p class="home-tips">由信网传媒提供技术支持</p>
        </div>
        <image-cropper ref="imageCropperRef"
                       :imgSrc="resultBase64"
                       @finish="cropperFinish"
                       @close="cropperClose"
        ></image-cropper>
        <take-photograph ref="takePhotoRef"
                         @finish="takePhotoFinish"
        ></take-photograph>
    </section>
</template>

<script type="text/ecmascript-6">
    import Headbar from '@/components/headbar/headbar';
    import ImageCropper from '@/components/image-cropper/image-cropper';
    import TakePhotograph from '@/components/take-photograph/take-photograph';

    import {readImage2Base64} from "@/common/js/functions";
    import {mapMutations,mapGetters} from 'vuex';

    export default {
        name: "home-page",
        emits: [''],
        components: {
            Headbar,
            ImageCropper,
            TakePhotograph
        },
        data() {
            return {
                resultBase64: ''
            }
        },
        created() {
          //  如果图片处于没加载完的状态 那么直接进入start
          //  防止有人从home分享出去
          if (!this.imgsLoaded) {
              this.$router.replace({
                  path: '/start'
              });
          }
        },
        computed: {
          ...mapGetters([
              'imgsLoaded'
          ])
        },
        methods: {
            async uploadPhoto(event) {
                const base64 = await readImage2Base64(event.target.files);
                this.resultBase64 = base64;
                if (this.resultBase64) {
                    this.$refs.imageCropperRef.show();
                }
                // 避免第二次传一样图片时候不触发
                event.target.value = '';
            },
            cropperFinish(base64) {
                this.resultBase64 = base64;
                this.gotoEdit();
            },
            cropperClose() {
                this.resultBase64 = '';
            },
            openCamera() {
                this.$refs.takePhotoRef.open();
            },
            takePhotoFinish(base64) {
                this.resultBase64 = base64;
                this.gotoEdit();
            },
            gotoEdit() {
                if (this.resultBase64) {
                    // 这一步仅修改原图
                    this.setPhotoOrigin(this.resultBase64);
                }
                this.$router.replace({
                    path: '/edit'
                });
            },
            ...mapMutations([
                'setPhoto',
                'setPhotoOrigin'
            ]),
        }
    }
</script>

<style lang="less" rel="stylesheet/less" scoped>
    .home-page {
        position: fixed;
        left: 0;
        right: 0;
        top: 0;
        bottom: 0;
        background: var(--color-deepgray);
        z-index: 10;
        overflow: auto;

        .home {
            position: absolute;
            left: 0;
            right: 0;
            bottom: 0;
            top: var(--height-headbar);

            .home-inner {
                display: flex;
                align-items: center;
                justify-content: center;
                height: 100%;
                width: 100%;
            }

            .home-select {
                width: 100%;
            }

            .select-show {
                width: 80%;
                padding-top: 80%;
                margin: 0 auto;
                background: url('homg-bg.png') no-repeat center center;
                background-size: cover;
            }

            .btn-upload,
            .btn-photo {
                display: block;
                text-align: center;
                width: 60%;
                margin: 0 auto;
                line-height: 50px;
                border-radius: 10px;
                color: #fff;
                font-size: 16px;

                .fa {
                    display: inline-block;
                    width: 24px;
                }
            }

            .btn-upload {
                background-color: #4994ec;
                margin: 40px auto 20px;

                input[type="file"] {
                    display: none;
                }
            }

            .btn-photo {
                background-color: #fc3e5a;
            }

            .home-tips {
                position: absolute;
                bottom: 0;
                color: #fff;
                font-size: 12px;
                text-align: center;
                left: 0;
                right: 0;
                padding-bottom: 20px;
            }
        }
    }
</style>
