<template>
    <teleport to="body">
    <transition name="photoAni"
                @after-enter="afterEnter"
    >
        <div class="take-photograph" v-show="showCamera">
            <headbar text="拍摄照片"></headbar>
            <div class="video-wrapper" :style="videoWrapperStyle">
                    <video ref="cameraVideoRef"
                           x-webkit-airplay="true"
                           x5-playsinline="true"
                           playsinline="true"
                           webkit-playsinline="true"
                           x5-video-player-type="h5"
                           x5-video-player-fullscreen="true"
                           x5-video-orientation="portraint"
                           :class="videoCls"
                    ></video>
            </div>

            <div class="take-controls" :style="controlsStyle">
                <div class="take-controls-flex">
                    <div class="take-controls-inner">
                        <div class="take-btn-wrapper">
                            <div class="take-btn" @click="takePicture"></div>
                        </div>
                        <div class="close" :class="{'close-more-top': takeBtnCls}">
                            <button type="button" @click="closeCamera">关闭</button>
                        </div>
                        <div class="turn-reversal" @click="toggleDirection">
                            <i class="icon-reversal"></i>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    </transition>
    </teleport>
</template>

<script type="text/ecmascript-6">
    import Headbar from '@/components/headbar/headbar';
    import wudialogs from '@/common/js/wudialogs';
    import { SCREEN_WIDTH, SCREEN_HEIGHT } from "@/common/js/const";

    // 摄像头要截取的尺寸
    const cropWidth = SCREEN_WIDTH - 20 * 2;
    const FACING = {
        // 前摄像头
        front: "user",
        // 后摄像头
        back: "environment"
    };
    const DEBUG = window.setting.debug;
    const controlsInnerHeight = 125;

    export default {
        name: "take-photograph",
        emits: [ 'finish' ],
        components: {
            Headbar
        },
        data() {
          return {
              // 是否能够拍照 避免点击拍照时候还未获取视频对象
              canTakePhoto: false,
              showCamera: false,
              // 摄像头朝向,默认后摄像头 调试模式为前摄像头
              facingMode: DEBUG ? FACING.front : FACING.back
          }
        },
        computed: {
            videoWrapperStyle() {
                return `width: ${cropWidth}px;height: ${cropWidth}px`;
            },
            videoCls() {
                return this.facingMode == FACING.front ? 'rotate180' : ''
            },
            controlsStyle() {
                // 摄像头取景框外边距20
                const top = cropWidth + 40 + 20;
                return `top: ${top}px`;
            },
            takeBtnCls() {
                const takeControlsHeight = SCREEN_HEIGHT - 40 - 20 - cropWidth;
                const diff = takeControlsHeight - controlsInnerHeight;
                console.log(diff)
                let res = false;
                if (diff > 50) {
                    res = true;
                }
                return res;
            }
        },
        methods: {
            async open() {
                const hasCamera = await this.checkCamera();
                if (!hasCamera) {
                    wudialogs.alert('抱歉，未检测到您设备上的摄像头');
                    return;
                }
                this.showCamera = true;
            },
            // 切换摄像头方向
            toggleDirection() {
                // 调式模式下不支持切换
                if (DEBUG) {
                    wudialogs.alert('当前为调试模式，不支持切换摄像头方向');
                    return;
                }
                // 切换的时候设置为false
                this.canTakePhoto = false;

                if (this.facingMode == FACING.front) {
                    this.facingMode = FACING.back;
                } else {
                    this.facingMode = FACING.front;
                }
                // 切换时先关闭
                this.$refs.cameraVideoRef.srcObject = null;
                this.getMedia();
            },
            checkCamera() {
                return new Promise((resolve) => {
                    // 摄像头和麦克风权限只在https和localhost下允许访问，不是本地mediaDevices直接没有
                    const navigator = window.navigator.mediaDevices;
                    if (!navigator) {
                        resolve(false);
                    } else {
                        //  enumerateDevices 函数来查看当前媒体设备是否存在。它的返回值是一个 promise 类型
                        navigator.enumerateDevices()
                            .then((devices) => {
                                resolve(Array.isArray(devices) && devices.length > 0);
                            })
                            .catch(() => {
                                resolve(false);
                            });
                    }
                });
            },
            afterEnter() {
                this.getMedia();
            },
            async getMedia() {
                const exact = this.facingMode;
                try {
                    const navigator = window.navigator.mediaDevices;
                    // 获取摄像流数据
                    const stream = await navigator.getUserMedia({
                        // 不需要音频 所以设置为false
                        audio: false,
                        video: {
                            width: cropWidth,
                            height: cropWidth,
                            // 强制后置摄像头
                            facingMode: {
                                // user 前置摄像头
                                // exact: "environment" 后置摄像头
                                exact: exact
                            }
                        }
                    });

                    this.canTakePhoto = true;

                    if (!this.$refs.cameraVideoRef) {
                        return;
                    }
                    this.$refs.cameraVideoRef.srcObject = stream;
                    this.$refs.cameraVideoRef.play();
                } catch (e) {
                    // 如果在用户授权界面，点击-取消
                    wudialogs.alert('请您“同意”，以便我们开启您的摄像头权限');
                    this.closeCamera();
                }
            },
            closeCamera() {
                this.$refs.cameraVideoRef.srcObject = null;
                this.showCamera = false;
                this.canTakePhoto = false;
            },
            takePicture() {
                if (!this.canTakePhoto) {
                    return;
                }
                const canvas = document.createElement("canvas");
                const videoEl = this.$refs.cameraVideoRef;
                canvas.width = videoEl.videoWidth;
                canvas.height = videoEl.videoHeight;

                const ctx = canvas.getContext("2d");

                // 如果是前置摄像头 那么就需要对canvas进行翻转
                if (this.facingMode == FACING.front) {
                    ctx.scale(-1, 1);
                    ctx.translate(-videoEl.videoWidth, 0);
                }

                ctx.drawImage(videoEl, 0, 0, canvas.width, canvas.height);
                const base64 = canvas.toDataURL("image/png", 1);

                // DEBUG && this.openBase64(base64);

                this.$emit('finish', base64);

                this.closeCamera();
            },
            openBase64(base64) {
                const img = new window.Image();
                img.src = base64;

                const newWin = window.open('');
                newWin.document.body.style.background = '#000';
                newWin.document.body.style.textAlign = 'center';
                newWin.document.body.appendChild(img);
                newWin.document.title = '图片预览';
                newWin.document.close();
            }
        }
    }
</script>

<style lang="less" rel="stylesheet/less" scoped>
    .take-photograph {
        position: fixed;
        top: 0;
        left: 0;
        right: 0;
        bottom: 0;
        background-color: var(--color-deepgray);
        z-index: 100;

        .video-wrapper{
            margin: 20px auto 0;
            border: 1px solid #000;
            background: #4b4b4b url("icon-camera.svg") center center no-repeat;

            /* 前置摄像头 图像会被反转,使用样式进行纠正 */
            video.rotate180{
                transform: rotateY(180deg);
            }
        }

        .take-btn-wrapper{
            display: flex;
            justify-content: center;
        }

        .take-btn{
            background-color: rgba(255,255,255,0.5);
            width: 60px;
            height: 60px;
            border-radius: 50%;
            display: flex;
            justify-content: center;
            align-items: center;
            &:before{
                content: "";
                width: 75%;
                height: 75%;
                display: block;
                background-color: #fff;
                border-radius: 50%;
            }
        }

        .take-controls{
            position: absolute;
            bottom: 0;
            left: 0;
            right: 0;
        }
        .take-controls-flex{
            display: flex;
            align-items: center;
            justify-content: center;
            flex-wrap: wrap;
            width: 100%;
            height: 100%;
        }
        .take-controls-inner{
            width: 100%;
            position: relative;
        }

        .turn-reversal{
            text-align: center;
            width: 60px;
            height: 60px;
            line-height: 60px;
            text-align: center;
            position: absolute;
            right: 0;
            top: 0px;
        }
        .icon-reversal{
            display: inline-block;
            width: 30px;
            height: 30px;
            background: url("icon-reversal .svg") no-repeat center center;
            background-size: cover;
        }

        .close{
            text-align: center;
            padding: 20px 0 0;
            &.close-more-top{
                padding-top: 40px;
            }
            button{
                width: 40%;
                height: 45px;
                background-color: var(--color-deepgray-l);
                color: #fff;
                font-size: 14px;
            }
        }
    }

    .photoAni-enter-active,
    .photoAni-leave-active {
        transition: all 0.3s;
    }

    .photoAni-enter-from,
    .photoAni-leave-to {
        transform: translate3d(100%, 0, 0);
        opacity: 0;
    }
</style>
