import {getQueryStringArgs} from "./functions";
// 项目目录
export const PUBLIC_PATH = process.env.BASE_URL;

// 资源汇总文件夹
export const ASSETS_PATH = window.setting.assets_path;

// 获取查询字符串内容
export const ID = (() => {
    const querys = getQueryStringArgs();
    const QUERY_ID = querys.id ? querys.id : 'spring';
    return QUERY_ID;
})();

export const DEBUG = window.setting.debug || false;

// window.screen.height是手机屏幕高度 这里要改为屏幕可用工作区高度
export const SCREEN_WIDTH = Math.floor(window.innerWidth);
export const SCREEN_HEIGHT = Math.floor(window.innerHeight);
// 生成海报的背景固定宽高
export const POP_WIDTH = 750;
export const POP_HEIGHT = 1624;
export const HEADBAR_HEIGHT = 40;

export const TIME_STRAMP = window.setting.assets_timestramp;

export const POP_CREATE_STATUS = {
    donot: 0,
    doing: 1,
    done: 2,
    fail: 3
};

// 判断安卓还是苹果
export const IS_IOS = (() => {
    let reg = /iphone|ipod|ipad|Macintosh/i;
    return reg.test(navigator.userAgent.toLowerCase());
})();

export const QR_QDXIN = 'https://ssl.qdxin.cn/api.tech/qrxin.php';
