<template>
    <transition name="fadeIn">
        <teleport to="body">
            <section class="waiting" v-show="showWaiting">
                <p class="waiting-text">{{ tips }}</p>
            </section>
        </teleport>
    </transition>
</template>

<script type="text/ecmascript-6">
    export default {
        name: "waiting-comp",
        props: {
          tips: {
              type: String,
              default() {
                  return '';
              }
          }
        },
        data() {
            return {
                showWaiting: false
            }
        },
        methods: {
            open() {
                this.showWaiting = true;
            },
            close() {
                this.showWaiting = false;
            }
        }
    }
</script>

<style lang="less" rel="stylesheet/less" scoped>
    .waiting {
        position: fixed;
        left: 0;
        right: 0;
        top: 0;
        bottom: 0;
        background: rgba(0,0,0,0.8) url("loading-pc.gif") center center no-repeat;
        z-index: 9999999;

        .waiting-text{
            position: absolute;
            top: 50%;
            color: #fff;
            left: 0;
            right: 0;
            text-align: center;
            height: 40px;
            line-height: 40px;
            margin-top: 12px;
        }
    }
</style>
