<template>
    <div class="card-page">
        <headbar :text="textConfig.text_card_head"></headbar>
        <!--  截图绘制区   -->
        <div class="card-canvas"
             :style="canvasStyle"
             id="card-canvas"
        >
            <img :src="base64Photo"
                 :style="photoStyle"
                 class="img-photo"
                 ref="imgPhotoRef"
            >
            <img :src="bgSrc" class="img-bg" ref="imgBgRef">
            <p class="text-p" :style="textStyle">{{ popText }}</p>
        </div>
        <!--  截图绘制区 end  -->
        <div class="card-wrapper">
            <div class="card-flex">
                <div class="card-inner">
                    <div class="card-show"
                         :style="cardshowStyle"
                    >
                        <img :src="base64Pop">
                    </div>
                    <div class="card-tips">
                        长按图片并下载到本地相册
                    </div>
                    <div class="control">
                        <div class="control-inner">
                            <div class="control-top">
                                <button type="button" class="btn-again" @click="doAgain">
                                    <i class="fa fa-refresh"></i> 再做一个
                                </button>
                            </div>
                            <div class="control-bottom">
                                <button type="button" class="btn-edit" @click="back2Edit">
                                    返回修改
                                </button>
                                <button type="button" class="btn-seebig" @click="openFullImage">
                                    查看大图
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
        <full-screen-img :imgsrc="base64Pop" ref="fullScreenImgRef"></full-screen-img>
    </div>
</template>

<script type="text/ecmascript-6">
    import Headbar from '@/components/headbar/headbar';
    import FullScreenImg from '@/components/full-screen-img/full-screen-img'
    /* eslint-disable */
    import {getAssets, openBase64, imgLoaded} from "@/common/js/functions";
    /* eslint-disable */
    import {screenShots} from "@/common/js/html2image";
    import wuDialog from '@/common/js/wudialogs';

    import {mapGetters, mapMutations, mapActions} from 'vuex';
    import {SCREEN_HEIGHT, POP_WIDTH, POP_HEIGHT, HEADBAR_HEIGHT, DEBUG, POP_CREATE_STATUS} from "@/common/js/const";

    const CONTROL_HEIGHT = 140;
    const CARDTIPS_HEIGHT = 30;

    export default {
        name: "card-page",
        components: {
            Headbar,
            FullScreenImg
        },
        data() {
            return {}
        },
        created() {},
        // 添加路由钩子函数 在进入之前执行
        beforeRouteEnter(to, from, next) {
            // console.log(next)
            next(vm => {
                // console.log(vm);
                vm.setPopStatus(POP_CREATE_STATUS.doing);
            });
        },
        computed: {
            bgSrc() {
                let src = '';
                if (this.pasters.length <= 0) {
                    src = getAssets('alpha-inimages.png');
                } else {
                    const pasterObj = this.pasters[this.pasterCurrent];
                    // 如果不支持文字
                    if (!this.textConfig.text_support ||
                        !this.popText
                    ) {
                        src = getAssets(pasterObj.no_text);
                    } else {
                        src = getAssets(pasterObj.has_text);
                    }
                }
                return src;
            },
            cardshowStyle() {
                const height = SCREEN_HEIGHT - HEADBAR_HEIGHT - CONTROL_HEIGHT - CARDTIPS_HEIGHT - 20;
                const width = Math.floor((POP_WIDTH / POP_HEIGHT) * height);
                return `width: ${width}px;height: ${height}px;`;
            },
            canvasStyle() {
                const height = SCREEN_HEIGHT - HEADBAR_HEIGHT;
                console.log(SCREEN_HEIGHT, height, window.screen.height, document.body.clientHeight, window.innerHeight)
                const width = Math.floor((POP_WIDTH / POP_HEIGHT) * height);
                return `width: ${width}px;height: ${height}px;`;
            },
            photoStyle() {
                // 获取外层的宽高
                const height = SCREEN_HEIGHT - HEADBAR_HEIGHT;
                const photoCss = this.popBg.photo_css;
                let styleStr = '';
                for (let key in photoCss) {
                    const valueOrigin = photoCss[key];
                    let value = 0;
                    if (typeof valueOrigin == 'number') {
                        // 利用高度 取到相对于
                        value = Math.ceil((valueOrigin / POP_HEIGHT) * height);
                        value = `${value}px`;
                    } else {
                        value = valueOrigin;
                    }

                    styleStr += `${key}:${value};`;
                }
                return styleStr;
            },
            textStyle() {
                const height = SCREEN_HEIGHT - HEADBAR_HEIGHT;
                const textCss = this.popBg.text_css;
                let styleStr = '';
                for (let key in textCss) {
                    const valueOrigin = textCss[key];
                    let value = 0;
                    if (typeof valueOrigin == 'number') {
                        // 利用高度 取到相对于
                        value = Math.ceil((valueOrigin / POP_HEIGHT) * height);
                        value = `${value}px`;
                    } else {
                        value = valueOrigin;
                    }
                    styleStr += `${key}:${value};`;
                }
                // console.log(styleStr)
                return styleStr;
            },
            ...mapGetters([
                'textConfig',
                'base64Photo',
                'base64Pop',
                'popText',
                'popBg',
                'popCreateStatus',
                'pasterCurrent',
                'pasters'
            ])
        },
        methods: {
            openFullImage() {
                if (this.checkIsDoing()) {
                    return;
                }

                this.$refs.fullScreenImgRef.open();
            },
            back2Edit() {
                if (this.checkIsDoing()) {
                    return;
                }

                // 返回时清空海报 并且 修改状态
                this.setPop('');
                this.setPopStatus(POP_CREATE_STATUS.donot);
                this.$router.replace({
                    path: '/edit'
                });
            },
            doAgain() {
                if (this.checkIsDoing()) {
                    return;
                }
                this.resetData();
                this.$router.replace({
                    path: '/home'
                });
            },
            // 检测是否正在合成
            checkIsDoing() {
                let status = true;
                if (this.popCreateStatus != POP_CREATE_STATUS.doing) {
                    status = false;
                } else {
                    wuDialog.msg('图片合成中，请稍候');
                }
                return status;
            },
            synthesisCard() {
                setTimeout(() => {
                    if (!this.base64Photo) {
                        return;
                    }
                    const photoEl = this.$refs.imgPhotoRef;
                    const bgEl = this.$refs.imgBgRef;
                    // 两张图片都加载完成后才截图
                    Promise.all([
                        imgLoaded(photoEl),
                        imgLoaded(bgEl)
                    ]).then(() => {
                        screenShots('card-canvas')
                            .then((base64) => {
                                // DEBUG && openBase64(base64);
                                this.setPop(base64);
                                this.setPopStatus(POP_CREATE_STATUS.done);
                            })
                            .catch(() => {
                                this.setPopStatus(POP_CREATE_STATUS.fail);
                                wuDialog.alert('图片合成失败，请您稍候重试');
                            });
                    }).catch((err) => {
                        this.setPopStatus(POP_CREATE_STATUS.fail);
                        wuDialog.alert('抱歉，图片加载遇到错误，请重试');
                        console.log(err);
                    });
                }, 1000);
            },
            ...mapMutations([
                'setPop',
                'setPopStatus'
            ]),
            ...mapActions([
                'resetData'
            ])
        },
        watch: {
            popCreateStatus(newval) {
                if (newval == POP_CREATE_STATUS.doing) {
                    this.$nextTick(() => {
                        this.synthesisCard();
                    });
                }
            },
            base64Photo: {
                handler(newVal) {
                    if (!newVal) {
                        this.$router.replace({
                            path: '/home'
                        });
                        this.setPopStatus(POP_CREATE_STATUS.donot);
                    }
                },
                immediate: true
            }
        }
    }
</script>

<style lang="less" rel="stylesheet/less" scoped>
    @controlHeight: 140px;

    .card-page {
        position: fixed;
        left: 0;
        right: 0;
        top: 0;
        bottom: 0;
        background-color: var(--color-deepgray);
        overflow: auto;

        .card-wrapper {
            position: absolute;
            top: var(--height-headbar);
            right: 0;
            left: 0;
            bottom: 0;
            background-color: var(--color-deepgray);
            z-index: 10;
            /*opacity: 0;*/

            .card-flex {
                width: 100%;
                height: 100%;
                /*display: flex;*/
                /*align-items: center;*/
                /*justify-content: center;*/
            }

            .card-inner {
                padding-top: 20px;
                width: 100%;
                height: 100%;
            }

            .card-show {
                background-color: #3d3d3d;
                background-image: url("loading-pc.gif");
                background-repeat: no-repeat;
                background-position: center center;
                margin: 0 auto;
            }

            .card-tips {
                color: #fff;
                text-align: center;
                font-size: 12px;
                line-height: 30px;
                height: 30px;
            }
        }

        .card-canvas {
            margin: 0 auto;
            position: relative;

            .img-bg {
                position: relative;
                z-index: 2;
            }

            .img-photo {
                position: absolute;
                z-index: 1;
            }

            .text-p {
                position: absolute;
                z-index: 2;
            }
        }

        .control {
            width: 70%;
            margin: 0 auto;
            height: @controlHeight;
            display: flex;
            align-items: center;

            .control-inner {
                width: 100%;
                margin-top: -10px;
            }

            .control-top {
                padding: 0px 0 10px;
            }

            .control-bottom {
                display: flex;
                justify-content: space-between;

                button {
                    width: 48%;
                    line-height: 40px;
                    height: 40px;
                    font-size: 14px;
                    color: #fff;
                }

                .btn-edit {
                    background-color: var(--color-deepgray-l);
                }

                .btn-seebig {
                    background-color: var(--color-btnblue);
                }
            }

            .btn-again {
                background-color: var(--color-btnred);
                color: #fff;
                width: 100%;
                line-height: 40px;
                font-size: 16px;

                .fa {
                    display: inline-block;
                    width: 20px;
                }
            }
        }
    }
</style>
